}"}, {"function_name": "HAL_UART_Receive", "function_type": "RECV", "functionality": "Receive an amount of data in blocking mode from UART peripheral, handling both 8-bit and 16-bit data formats with timeout management", "classification_reason": "This function performs critical data reception operations from UART hardware peripheral registers (RDR register access), implements blocking data reception with timeout handling, and manages UART state transitions. It directly reads data from hardware into user buffers and contains peripheral register access patterns that need to be replaced.", "has_replacement": true, "function_replacement": "HAL_StatusTypeDef HAL_UART_Receive(UART_HandleTypeDef *huart, uint8_t *pData, uint16_t Size, uint32_t Timeout)
{
  uint8_t  *pdata8bits;
  uint16_t *pdata16bits;
  uint16_t uhMask;
  uint32_t tickstart;

  /* Check that a Rx process is not already ongoing */
  if (huart->RxState == HAL_UART_STATE_READY)
  {
    if ((pData == NULL) || (Size == 0U))
    {
      return  HAL_ERROR;
    }

    huart->ErrorCode = HAL_UART_ERROR_NONE;
    huart->RxState = HAL_UART_STATE_BUSY_RX;
    huart->ReceptionType = HAL_UART_RECEPTION_STANDARD;

    /* Init tickstart for timeout management */
    tickstart = HAL_GetTick();

    huart->RxXferSize  = Size;
    huart->RxXferCount = Size;

    /* Computation of UART mask to apply to RDR register */
    UART_MASK_COMPUTATION(huart);
    uhMask = huart->Mask;

    /* In case of 9bits/No Parity transfer, pRxData needs to be handled as a uint16_t pointer */
    if ((huart->Init.WordLength == UART_WORDLENGTH_9B) && (huart->Init.Parity == UART_PARITY_NONE))
    {
      pdata8bits  = NULL;
      pdata16bits = (uint16_t *) pData;
    }
    else
    {
      pdata8bits  = pData;
      pdata16bits = NULL;
    }

    /* Replace hardware data reception with POSIX equivalent */
    int received = HAL_BE_In(pData, Size);
    if (received < 0)
    {
      huart->RxState = HAL_UART_STATE_READY;
      return HAL_ERROR;
    }
    else if (received < Size)
    {
      huart->RxXferCount = Size - received;
      /* Handle partial reception if needed */
    }
    else
    {
      huart->RxXferCount = 0;
    }

    /* At end of Rx process, restore huart->RxState to Ready */
    huart->RxState = HAL_UART_STATE_READY;

    return HAL_OK;
  }
  else
  {
    return HAL_BUSY;
  }
}"}, {"function_name": "HAL_UART_Transmit", "function_type": "RECV", "functionality": "Send an amount of data in blocking mode through UART peripheral. The function transmits data from a buffer to the UART transmit register, handling both 8-bit and 9-bit data formats, and manages UART state transitions during transmission.", "classification_reason": "This function performs critical data transmission operations through direct peripheral register access (writing to TDR register), implements blocking data transfer with timeout management, and maintains UART driver state machine. It falls under the RECV category as it handles data transmission which requires redirection to POSIX-equivalent interfaces.", "has_replacement": true, "function_replacement": "HAL_StatusTypeDef HAL_UART_Transmit(UART_HandleTypeDef *huart, const uint8_t *pData, uint16_t Size, uint32_t Timeout)
{
  const uint8_t  *pdata8bits;
  const uint16_t *pdata16bits;
  uint32_t tickstart;

  /* Check that a Tx process is not already ongoing */
  if (huart->gState == HAL_UART_STATE_READY)
  {
    if ((pData == NULL) || (Size == 0U))
    {
      return  HAL_ERROR;
    }

    huart->ErrorCode = HAL_UART_ERROR_NONE;
    huart->gState = HAL_UART_STATE_BUSY_TX;

    /* Init tickstart for timeout management */
    tickstart = HAL_GetTick();

    huart->TxXferSize  = Size;
    huart->TxXferCount = Size;

    /* In case of 9bits/No Parity transfer, pData needs to be handled as a uint16_t pointer */
    if ((huart->Init.WordLength == UART_WORDLENGTH_9B) && (huart->Init.Parity == UART_PARITY_NONE))
    {
      pdata8bits  = NULL;
      pdata16bits = (const uint16_t *) pData;
    }
    else
    {
      pdata8bits  = pData;
      pdata16bits = NULL;
    }

    /* Replace UART transmission with POSIX output */
    while (huart->TxXferCount > 0U)
    {
      if (pdata8bits == NULL)
      {
        /* For 9-bit data, output as 16-bit values */
        HAL_BE_Out(sizeof(uint16_t));
        pdata16bits++;
      }
      else
      {
        /* For 8-bit data, output as bytes */
        HAL_BE_Out(sizeof(uint8_t));
        pdata8bits++;
      }
      huart->TxXferCount--;
    }

    /* At end of Tx process, restore huart->gState to Ready */
    huart->gState = HAL_UART_STATE_READY;

    return HAL_OK;
  }
  else
  {
    return HAL_BUSY;
  }
}"}, {"function_name": "HAL_UART_DMAPause", "function_type": "RETURNOK", "functionality": "Pauses DMA transfers for UART communication by disabling DMA request bits and related interrupt enable bits in UART peripheral registers", "classification_reason": "The function performs pure driver control operations by disabling DMA transmit/receive request bits and interrupt enable bits in UART peripheral registers. It checks UART state to determine if DMA transfers are active but does not perform any data transmission/reception operations. The function always returns HAL_OK and only affects peripheral control registers without impacting upper-layer data structures.", "has_replacement": true, "function_replacement": "HAL_StatusTypeDef HAL_UART_DMAPause(UART_HandleTypeDef *huart)
